def safe_json_path_lookup(data: dict | list, path: str, default: any = None) -> any:
    if not path:
        return data

    components = path.split('.')
    current = data

    for component in components:
        if component.isdigit():
            component = int(component)
        if isinstance(current, dict) and component in current:
            current = current[component]
        elif isinstance(current, list) and 0 <= component < len(current):
            current = current[component]
        else:
            return default

    return current

